    assert remove_elements([3, 1, 3, 2, 1], [1]) == [3, 3, 2]


def test_strings():
    assert remove_elements(["a", "b", "c"], ["b"]) == ["a", "c"]


def test_unhashable_elements():
    assert remove_elements([[1], [2], [3]], [[2]]) == [[1], [3]]


def test_does_not_mutate_inputs():
    list1 = [1, 2, 3]
    list2 = [2]
    assert remove_elements(list1, list2) == [1, 3]
